@php
    $themeOrganization = (isset($organization) && $organization instanceof \App\Models\Organization) ? $organization : null;
    $safeColor = fn ($color, $fallback) => is_string($color) && preg_match('/^#[0-9a-fA-F]{6}$/', $color) ? $color : $fallback;
    $primary = $safeColor($themeOrganization?->primary_color, '#2459a6');
    $accent = $safeColor($themeOrganization?->accent_color, '#12856f');
    $contrastText = function ($hex) {
        $parts = [hexdec(substr($hex,1,2)), hexdec(substr($hex,3,2)), hexdec(substr($hex,5,2))];
        $linear = array_map(function ($c) { $c=$c/255; return $c <= 0.04045 ? $c/12.92 : (($c+0.055)/1.055)**2.4; }, $parts);
        return (0.2126*$linear[0] + 0.7152*$linear[1] + 0.0722*$linear[2]) > 0.179 ? '#000000' : '#ffffff';
    };
    $member = auth()->check() && $themeOrganization && $themeOrganization->users()->where('users.id',auth()->id())->exists();
    $hasEmployee = $member && \App\Models\Employee::where('organization_id',$themeOrganization->id)->where('user_id',auth()->id())->exists();
    $can = fn($key) => auth()->check() && $themeOrganization && auth()->user()->hasPermission($key,$themeOrganization);
    $self = fn($key) => auth()->check() && auth()->user()->hasPermission($key);
    $groups = [];
    if(auth()->check()) {
        $groups['Overview'][]=['label'=>'Organizations','route'=>'home','icon'=>'home','active'=>request()->routeIs('home')];
        if($themeOrganization) {
            if($can('organization.view')) $groups['Overview'][]=['label'=>'Organization workspace','route'=>'organizations.show','icon'=>'building','active'=>request()->routeIs('organizations.show')];
            if($member && $self('profile.self.view')) $groups['My workspace'][]=['label'=>'My profile','route'=>'self-profile.show','icon'=>'user','active'=>request()->routeIs('self-profile.*')];
            if($hasEmployee && $self('leave.self.view')) $groups['My workspace'][]=['label'=>'My leave','route'=>'leave.mine','icon'=>'calendar','active'=>request()->routeIs('leave.mine')];
            if($hasEmployee && $self('attendance.self.view')) $groups['My workspace'][]=['label'=>'My attendance','route'=>'attendance.mine','icon'=>'clock','active'=>request()->routeIs('attendance.mine')];
            if($hasEmployee && $self('overtime.self.view')) $groups['My workspace'][]=['label'=>'My overtime','route'=>'overtime.mine','icon'=>'clock','active'=>request()->routeIs('overtime.mine')];
            if($hasEmployee && $self('training.self.view')) $groups['My workspace'][]=['label'=>'My training','route'=>'training.mine','icon'=>'book','active'=>request()->routeIs('training.mine','assessment.take')];
            if($hasEmployee && $self('lifecycle.self.view')) $groups['My workspace'][]=['label'=>'My checklists','route'=>'lifecycle.self','icon'=>'list','active'=>request()->routeIs('lifecycle.self')];
            if($member && $self('daily.notifications.view')) $groups['My workspace'][]=['label'=>'Notifications','route'=>'daily.notifications','icon'=>'bell','active'=>request()->routeIs('daily.notifications')];
            if($member && $hasEmployee && $self('lifecycle.self.notifications.view')) $groups['My workspace'][]=['label'=>'Checklist notifications','route'=>'lifecycle.notifications','icon'=>'bell','active'=>request()->routeIs('lifecycle.notifications')];
            if($can('employees.view')) $groups['People'][]=['label'=>'Employees','route'=>'employees.index','icon'=>'users','active'=>request()->routeIs('employees.*','documents.*')];
            if($can('recruitment.vacancies.view')) $groups['People'][]=['label'=>'Recruitment','route'=>'recruitment.index','icon'=>'users','active'=>request()->routeIs('recruitment.*')];
            if($can('lifecycle.cases.view')) $groups['People'][]=['label'=>'Employee lifecycle','route'=>'lifecycle.cases','icon'=>'list','active'=>request()->routeIs('lifecycle.cases')];
            if($can('attendance.records.view')) $groups['Operations'][]=['label'=>'Attendance','route'=>'attendance.records','icon'=>'clock','active'=>request()->routeIs('attendance.records')];
            if($can('overtime.requests.view')) $groups['Operations'][]=['label'=>'Overtime requests','route'=>'overtime.index','icon'=>'clock','active'=>request()->routeIs('overtime.index')];
            if($can('leave.requests.view') || $can('leave.requests.view_all') || $can('leave.requests.supervisor_approve') || $can('leave.requests.officer_approve')) $groups['Operations'][]=['label'=>'Leave requests','route'=>'leave.reviews','icon'=>'calendar','active'=>request()->routeIs('leave.reviews')];
            if($can('leave.types.view')) $groups['Operations'][]=['label'=>'Leave types','route'=>'leave.types','icon'=>'calendar','active'=>request()->routeIs('leave.types')];
            if($can('leave.holidays.view')) $groups['Operations'][]=['label'=>'Holidays','route'=>'holidays.index','icon'=>'calendar','active'=>request()->routeIs('holidays.*')];
            if($can('leave.approvers.view')) $groups['Operations'][]=['label'=>'Approving officers','route'=>'leave.officers','icon'=>'users','active'=>request()->routeIs('leave.officers')];
            if($member && ($can('chat.general.view') || $can('chat.direct.view'))) $groups['Operations'][]=['label'=>'Staff chat','route'=>'chat.index','icon'=>'chat','active'=>request()->routeIs('chat.*')];
            if($can('training.courses.view')) $groups['Development'][]=['label'=>'Training management','route'=>'training.index','icon'=>'book','active'=>request()->routeIs('training.index','assessment.manage','assessment.results')];
            foreach(['performance'=>'Performance','training'=>'Training records','qualifications'=>'Qualifications','career'=>'Career development'] as $area=>$label) if($can("development.$area.view")) $groups['Development'][]=['label'=>$label,'route'=>'development.index','area'=>$area,'icon'=>'book','active'=>request()->routeIs('development.index') && request()->route('area')===$area];
        }
    }
