<script>(function(){const btn=document.getElementById('sidebar-toggle'),overlay=document.getElementById('menu-overlay'),wide=window.matchMedia('(min-width:901px)');try{if(localStorage.getItem('hr-sidebar-collapsed')==='true'&&wide.matches)document.body.classList.add('nav-collapsed')}catch(e){}function sync(){btn.setAttribute('aria-expanded',String(wide.matches?!document.body.classList.contains('nav-collapsed'):document.body.classList.contains('nav-open')))}btn.addEventListener('click',()=>{if(wide.matches){document.body.classList.toggle('nav-collapsed');try{localStorage.setItem('hr-sidebar-collapsed',String(document.body.classList.contains('nav-collapsed')))}catch(e){}}else document.body.classList.toggle('nav-open');sync()});overlay.addEventListener('click',()=>{document.body.classList.remove('nav-open');sync()});wide.addEventListener('change',()=>{document.body.classList.remove('nav-open');sync()});sync()})();</script>@endauth</body></html>
